'use strict';
function renderReadableReport(){let root=$('#readable-report');if(root.dataset.ready)return;root.dataset.ready='1';let current=null;for(let b of RELATORIO_CONTEUDO){if(b.type==='heading'){current=document.createElement('details');current.className='report-section';current.innerHTML='<summary>'+esc(b.text)+'</summary>';root.append(current);continue}if(!current)continue;let body='';if(b.type==='paragraph')body='<p>'+esc(b.text).replace(/https:\/\/[^\s]+/g,u=>'<a href="'+u+'" target="_blank" rel="noopener">'+u+'</a>')+'</p>';if(b.type==='table')body=mlTable(b.headers,b.rows.map(r=>r.map(v=>esc(v))));if(b.type==='image')body='<figure><img loading="lazy" src="exports/'+b.file+'" alt="'+esc(b.caption)+'"><figcaption>'+esc(b.caption)+'</figcaption></figure>';if(b.type==='source')body='<div class="source-entry"><b>'+esc(b.file)+'</b><p>'+N(b.bytes)+' bytes · '+esc(b.time)+'</p><p><a href="'+esc(b.url)+'" target="_blank" rel="noopener">Arquivo oficial ↗</a></p><code>SHA256 '+esc(b.sha)+'</code></div>';current.insertAdjacentHTML('beforeend',body)}root.querySelector('details').open=true;$('#report-summary').innerHTML='<b>Estado da entrega</b><p>Dados auditados, análises estatísticas e três experimentos de machine learning executados; 16 células no notebook com saídas preservadas. A interpretação identifica ganhos modestos e limites. Governança causal, detecção de eventos ocultos e resposta histórica continuam dependentes de evidência adicional.</p>'}
const reportRender=render;render=function(){reportRender();if(state.page==='laboratorio')renderReadableReport()};page(location.hash.slice(1)||'visao');
